  let max = 0;
  let curr = 0;
  const timeline = {};
  for (let i = 0; i < arr.length; i++) {
    const start = arr[i][0];
    const end = arr[i][1];
    timeline[start] = (timeline[start] || 0) + 1;
    timeline[end] = (timeline[end] || 0) - 1;
  }
  for (const key in timeline) {
    curr += timeline[key];
    max = Math.max(max, curr);
  }
  return max;
