{ 
    int length = 0; 
    char temp; 

    // calculate the length of string 
    while (*str != 0) { 
        length++; 
        str++; 
    } 

    // the end of string 
    str--; 

    // swap first and last characters 
    for (int i = 0; i < length/2; i++) 
    { 
        temp = *str; 
        *str = *(str - length + 1); 
        *(str -length + 1) = temp; 

        str--; 
    } 
}

